def get_perimeter(n):
    cells = set()
    for x in range(-n, n + 1):
        for y in range(-n, n + 1):
            if abs(x) + abs(y) <= n:
                cells.add((x, y))

    edges = set()
    for (x, y) in cells:
        # Check 4 edges of the cell
        for dx, dy, edge in [(0, 0, 'h'), (0, 1, 'h'), (0, 0, 'v'), (1, 0, 'v')]:
            # This is confusing. Let's use a better way to represent edges.
            pass

    # Better way to count boundary edges:
    # An edge is on the boundary if it belongs to exactly one cell in the set.
    all_edges = []
    for (x, y) in cells:
        # Cell (x,y) has 4 edges:
        # Horizontal edges: ((x,y), (x+1,y)) and ((x,y+1), (x+1,y+1))
        # Vertical edges: ((x,y), (x,y+1)) and ((x+1,y), (x+1,y+1))
        all_edges.append(((x, y), (x+1, y)))
        all_edges.append(((x, y+1), (x+1, y+1)))
        all_edges.append(((x, y), (x, y+1)))
        all_edges.append(((x+1, y), (x+1, y+1)))

    from collections import Counter
    counts = Counter(all_edges)
    boundary_edges = [edge for edge, count in counts.items() if count == 1]
    return len(boundary_edges)

for n in range(10):
    print(f"n={n}, perimeter={get_perimeter(n)}")
